using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace FinalAnswer {
 public sealed class StandaloneProbe:MonoBehaviour {
  IEnumerator Start(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-fa-host-smoke")>=0){yield return HostScreenSmoke.Run();yield break;}if(Array.IndexOf(Environment.GetCommandLineArgs(),"-fa-hall-smoke")>=0){yield return HallSmoke();yield break;}if(Array.IndexOf(Environment.GetCommandLineArgs(),"-fa-smoke")<0)yield break;GameManager.Instance.SelectGame(GameKind.LastCommand);float deadline=Time.realtimeSinceStartup+30;while((!GameManager.Instance||!GameManager.Instance.Machine||!GameManager.Instance.Machine.Ready)&&Time.realtimeSinceStartup<deadline)yield return null;var app=GameManager.Instance;if(!app||!app.Machine){Application.Quit(2);yield break;}string dir=Path.Combine(Application.persistentDataPath,"Smoke");Directory.CreateDirectory(dir);yield return new WaitForSecondsRealtime(2);FrameCapture.Write(app.Machine.CameraRig.Camera,Path.Combine(dir,"machine-front.png"));ScreenCapture.CaptureScreenshot(Path.Combine(dir,"desktop-ui.png"));
   var connect=app.Rooms.Development("http://127.0.0.1:18096");while(!connect.IsCompleted&&Time.realtimeSinceStartup<deadline)yield return null;if(connect.IsFaulted){Debug.LogError("STANDALONE_SERVER_FAILED");Application.Quit(3);yield break;}while(!app.Network.Authenticated&&Time.realtimeSinceStartup<deadline)yield return null;app.StartGame();yield return new WaitForSecondsRealtime(3);app.Action("CODE_PANEL","PREVIEW_TASK","MATH");yield return new WaitForSecondsRealtime(1);app.Machine.FocusCurrent();yield return new WaitForSecondsRealtime(1);FrameCapture.Write(app.Machine.CameraRig.Camera,Path.Combine(dir,"machine-terminal.png"));ScreenCapture.CaptureScreenshot(Path.Combine(dir,"connected-ui.png"));var frames=new List<float>();for(int i=0;i<180;i++){yield return null;frames.Add(Time.unscaledDeltaTime*1000);}frames.Sort();File.WriteAllText(Path.Combine(dir,"report.json"),new JObject{{"platform",Application.platform.ToString()},{"processor",SystemInfo.processorType},{"graphics",SystemInfo.graphicsDeviceName},{"unity",Application.unityVersion},{"connected",app.Network.Authenticated},{"task",app.Snapshots.Current.Obj("lastCommand").Obj("testRound").S("taskType")},{"frameTimeP95Ms",frames[(int)(frames.Count*.95f)]},{"sampleFrames",frames.Count}}.ToString());Debug.Log("STANDALONE_SMOKE_OK: "+dir);Application.Quit(0);
  }
  IEnumerator HallSmoke(){float until=Time.realtimeSinceStartup+30;while((!GameManager.Instance||!GameManager.Instance.Hall||!GameManager.Instance.Hall.Ready)&&Time.realtimeSinceStartup<until)yield return null;var app=GameManager.Instance;if(!app||!app.Hall){Application.Quit(2);yield break;}string dir=System.IO.Path.Combine(Application.persistentDataPath,"HallSmoke");Directory.CreateDirectory(dir);foreach(var kind in new[]{GameKind.Quiz,GameKind.CursedBoxes,GameKind.Impostor}){app.SelectGame(kind);yield return new WaitForSecondsRealtime(1);ScreenCapture.CaptureScreenshot(Path.Combine(dir,kind+"-lobby.png"));yield return new WaitForSecondsRealtime(.2f);}Debug.Log("HALL_STANDALONE_SMOKE_OK");Application.Quit(0);}
 }
}
